style.css:
@-moz-document domain("chatgpt.com") {
/* Body and Background */
    body {
        background-color: #0d0d0d;
        color: #e0e0e0;
        font-family: "Courier New", Courier, monospace;
        text-transform: uppercase;
        letter-spacing: 2px;
        animation: flicker 2s infinite alternate;
    }

    /* Links */
    a {
        color: #ff1a1a;
        text-decoration: none;
        padding: 2px; /* Smaller highlight area */
        transition: color 0.2s ease, text-shadow 0.2s ease;
    }

    a:hover {
        color: #ff4d4d;
        text-shadow: 0 0 5px #ff4d4d; /* Subtle glow */
    }

    /* Buttons */
    button {
        background-color: #330000;
        color: #ff4d4d;
        border: 1px solid #990000;
        padding: 5px 10px; /* Smaller buttons */
        font-size: 12px;
        font-weight: bold;
        cursor: pointer;
        text-shadow: 0 0 3px #990000;
        box-shadow: 0 0 5px rgba(255, 0, 0, 0.5);
        transition: transform 0.15s, box-shadow 0.15s;
    }

    button:hover {
        transform: scale(1.05); /* Slightly smaller scale */
        box-shadow: 0 0 10px rgba(255, 0, 0, 0.8);
    }

    /* Input Fields */
    input[type="text"], input[type="password"] {
        background-color: #1a1a1a;
        color: #ff4d4d;
        border: 1px solid #990000;
        padding: 5px; /* Compact input fields */
        font-size: 12px;
        width: 100%;
    }

    input[type="text"]:focus, input[type="password"]:focus {
        border-color: #ff0000;
        outline: none;
        box-shadow: 0 0 8px #ff0000;
    }

    /* Header */
    .header {
        background-color: #1a1a1a;
        padding: 10px; /* Smaller padding */
        text-align: center;
        border-bottom: 2px solid #990000;
    }

    .header h1 {
        color: #ff1a1a;
        font-size: 28px; /* Smaller font size */
        margin: 0;
        text-shadow: 0 0 5px #ff4d4d;
    }

    /* Footer */
    .footer {
        background-color: #1a1a1a;
        padding: 5px 0; /* Compact footer */
        text-align: center;
        border-top: 2px solid #990000;
        color: #ff4d4d;
        font-size: 12px;
    }

    /* Cards or Boxes */
    .card {
        background-color: #1a1a1a;
        color: #ff4d4d;
        border: 1px solid #990000;
        padding: 10px; /* Smaller card size */
        margin: 5px 0;
        box-shadow: 0 0 8px rgba(255, 0, 0, 0.5);
        transition: transform 0.2s;
    }

    .card:hover {
        transform: translateY(-5px); /* Smaller movement */
        box-shadow: 0 0 15px rgba(255, 0, 0, 0.8);
    }

    /* Animations */
    @keyframes flicker {
        0%, 100% {
            opacity: 1;
        }
        50% {
            opacity: 0.9;
        }
    }
}
